// bbx fixture: minimal MCP stdio server (newline-delimited JSON-RPC 2.0).
// argv[2] labels the instance so each configured server answers differently.
import readline from 'node:readline';
const label = process.argv[2] ?? 'unlabelled';
const send = (message) => process.stdout.write(JSON.stringify(message) + '\n');
const tool = {
  name: 'echo',
  description: 'Echo the given text back, prefixed with the server label (' + label + ').',
  inputSchema: {
    type: 'object',
    properties: { text: { type: 'string', description: 'Text to echo.' } },
    required: ['text'],
    additionalProperties: false,
  },
};
readline.createInterface({ input: process.stdin }).on('line', (line) => {
  let request;
  try { request = JSON.parse(line); } catch { return; }
  if (request.id === undefined) return; // notification
  if (request.method === 'initialize') {
    send({ jsonrpc: '2.0', id: request.id, result: {
      protocolVersion: request.params?.protocolVersion ?? '2024-11-05',
      capabilities: { tools: {} },
      serverInfo: { name: 'bbx-echo-' + label, version: '1.0.0' },
    } });
  } else if (request.method === 'tools/list') {
    send({ jsonrpc: '2.0', id: request.id, result: { tools: [tool] } });
  } else if (request.method === 'tools/call') {
    const text = String(request.params?.arguments?.text ?? '');
    send({ jsonrpc: '2.0', id: request.id, result: { content: [{ type: 'text', text: 'echo[' + label + ']: ' + text }] } });
  } else if (request.method === 'ping') {
    send({ jsonrpc: '2.0', id: request.id, result: {} });
  } else {
    send({ jsonrpc: '2.0', id: request.id, error: { code: -32601, message: 'Method not found: ' + request.method } });
  }
});
